// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListDataExchangeKinds Jenis data yang boleh diimpor/diekspor user (MD-10, INT-02)
	// (GET /api/v1/data-exchange/kinds)
	ListDataExchangeKinds(ctx context.Context, request ListDataExchangeKindsRequestObject) (ListDataExchangeKindsResponseObject, error)
	// GetDataExchangeTemplate Mengunduh template impor (xlsx) yang dihasilkan dari definisi kolom
	// (GET /api/v1/data-exchange/kinds/{kind}/template)
	GetDataExchangeTemplate(ctx context.Context, request GetDataExchangeTemplateRequestObject) (GetDataExchangeTemplateResponseObject, error)
	// ListExportJobs Riwayat ekspor (jenis data yang boleh diekspor user)
	// (GET /api/v1/export-jobs)
	ListExportJobs(ctx context.Context, request ListExportJobsRequestObject) (ListExportJobsResponseObject, error)
	// CreateExportJob Memulai ekspor ke xlsx
	// (POST /api/v1/export-jobs)
	CreateExportJob(ctx context.Context, request CreateExportJobRequestObject) (CreateExportJobResponseObject, error)
	// GetExportJob Status job ekspor
	// (GET /api/v1/export-jobs/{id})
	GetExportJob(ctx context.Context, request GetExportJobRequestObject) (GetExportJobResponseObject, error)
	// GetExportJobDownloadUrl URL unduhan file ekspor
	// (GET /api/v1/export-jobs/{id}/download-url)
	GetExportJobDownloadUrl(ctx context.Context, request GetExportJobDownloadUrlRequestObject) (GetExportJobDownloadUrlResponseObject, error)
	// ListImportJobs Riwayat impor (jenis data yang boleh diimpor user)
	// (GET /api/v1/import-jobs)
	ListImportJobs(ctx context.Context, request ListImportJobsRequestObject) (ListImportJobsResponseObject, error)
	// CreateImportJob Memulai impor dari file xlsx yang sudah diunggah
	// (POST /api/v1/import-jobs)
	CreateImportJob(ctx context.Context, request CreateImportJobRequestObject) (CreateImportJobResponseObject, error)
	// GetImportJob Status, progress, dan ringkasan job impor
	// (GET /api/v1/import-jobs/{id})
	GetImportJob(ctx context.Context, request GetImportJobRequestObject) (GetImportJobResponseObject, error)
	// CancelImportJob Membatalkan impor yang menunggu konfirmasi
	// (POST /api/v1/import-jobs/{id}/cancel)
	CancelImportJob(ctx context.Context, request CancelImportJobRequestObject) (CancelImportJobResponseObject, error)
	// CommitImportJob Menyimpan baris valid
	// (POST /api/v1/import-jobs/{id}/commit)
	CommitImportJob(ctx context.Context, request CommitImportJobRequestObject) (CommitImportJobResponseObject, error)
	// GetImportJobErrorFile URL unduhan file baris error (xlsx dengan kolom Keterangan Error)
	// (GET /api/v1/import-jobs/{id}/error-file)
	GetImportJobErrorFile(ctx context.Context, request GetImportJobErrorFileRequestObject) (GetImportJobErrorFileResponseObject, error)
	// ListImportJobRows Preview baris hasil pemeriksaan
	// (GET /api/v1/import-jobs/{id}/rows)
	ListImportJobRows(ctx context.Context, request ListImportJobRowsRequestObject) (ListImportJobRowsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

